negatives.text:
server {
    listen 4318;
    location /v1/ {
        proxy_set_header Host $host;
        proxy_pass http://otel-collector:4318;
    }
}

server {
    listen 4318;
    location /v1/ {
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_pass http://otel-collector:4318;
    }
}

server {
    listen 4318;
    location /v1/ {
        set $upstream "otel-collector:4318";
        proxy_pass http://otel-collector:4318;
    }
}

map $http_upgrade $connection_upgrade {
    default upgrade;
    '' close;
}

exporters:
  otlphttp:
    endpoint: https://otlp.example.invalid:4318
    headers:
      Authorization: ${env:OTLP_AUTH}
      api-key: ${env:OTLP_API_KEY}
      x-honeycomb-team: ${HONEYCOMB_KEY}

server {
    listen 4318;
    location /v1/ {
        proxy_set_header Authorization $http_authorization;
        proxy_set_header X-API-Key $http_x_api_key;
        proxy_set_header Cookie $http_cookie;
        grpc_set_header authorization $http_authorization;
        proxy_pass http://otel-collector:4318;
    }
}

server {
    listen 4318;
    location /v1/ {
        # proxy_set_header X-API-Key is set by the gateway, not here
        # the Authorization header is checked upstream (secure_link_secret is not used)
        proxy_pass http://otel-collector:4318;
    }
}

server {
    listen 4318;
    location /v1/ {
        ssl_certificate /etc/nginx/tls/server.crt;
        ssl_certificate_key /etc/nginx/tls/server.key;
        ssl_trusted_certificate /etc/nginx/tls/ca.pem;
        auth_basic "OTLP ingest";
        auth_basic_user_file /etc/nginx/conf.d/.htpasswd;
        proxy_pass http://otel-collector:4318;
    }
}

server {
    listen 4318;
    location /v1/ {
        set $api_token $arg_token;
        set $auth_header $http_authorization;
        proxy_pass http://otel-collector:4318;
    }
}

server {
    listen 4318;
    location /v1/ {
        if ($http_x_api_key = "") { return 401; }
        if ($http_authorization != $expected_auth) { return 403; }
        proxy_pass http://otel-collector:4318;
    }
}

map $http_authorization $has_auth {
    default 1;
    "" 0;
}
map $http_x_tenant $tenant_pool {
    default pool_default;
    "tenant-a" pool_a;
}

server {
    listen 4318;
    location /v1/ {
        secure_link $arg_md5,$arg_expires;
        proxy_pass http://otel-collector:4318;
    }
}
